<?php
$sql = "
CREATE TABLE IF NOT EXISTS " . TABLE_ZONES_TO_POST_CODE_JP . " (
    post_zone_id int NOT NULL AUTO_INCREMENT,
    zone_country_id int NOT NULL,
    zone_id int NOT NULL DEFAULT '0',
    post_code varchar(32) NOT NULL,
    zone_name varchar(32) NOT NULL,
    zone_city_name varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs_ks NOT NULL,
    zone_street_name varchar(70) CHARACTER SET utf8mb4 COLLATE utf8mb4_ja_0900_as_cs_ks DEFAULT '',
    zone_name_romaji varchar(32) NOT NULL,
    zone_city_name_romaji varchar(64) NOT NULL,
    zone_street_name_romaji varchar(88) DEFAULT '',
    PRIMARY KEY (post_zone_id),
    UNIQUE KEY idx_post_code_multiple_zen (post_code,zone_city_name,zone_street_name,zone_street_name_romaji),
    KEY idx_zone_id_zen (zone_id),
    KEY idx_zone_name_zen (zone_name),
    KEY idx_zone_name_romaji_zen (zone_name_romaji)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
";
$this->executeInstallerSql($sql);

$sql = "SET @coid = (SELECT countries_id FROM " . TABLE_COUNTRIES . " WHERE countries_iso_code_3 = 'JPN' ORDER BY countries_id DESC LIMIT 1);";
$this->executeInstallerSql($sql);

